import json

# Load tools.json
with open('tools.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# Find 开发工具 category
dev_cat_idx = None
for i, cat in enumerate(data):
    if cat['category'] == '开发工具':
        dev_cat_idx = i
        break

print(f"Found 开发工具 at index {dev_cat_idx}")

